-- ------------------------------------------------------------------ registrants
-- Next.js (Jan 2569): today's year 4+, who were in year 3 then.
INSERT INTO registrations (id, event_id, user_id, dept, status, checked_in, checked_in_at, attend_via, registered_at)
SELECT 105700 + ROW_NUMBER() OVER (ORDER BY u.id), 1057, u.id,
       CONCAT('นักศึกษาชั้นปีที่ ', CAST(REGEXP_SUBSTR(u.dept, '[0-9]+') AS UNSIGNED) - 1, SUBSTRING(u.dept, LOCATE(' · ', u.dept))),
       'attended', 1, TIMESTAMP('2026-01-11', SEC_TO_TIME(8 * 3600 + 5 * 60 + (u.id % 24) * 60)), 'onsite',
       TIMESTAMP('2025-12-22' + INTERVAL (u.id % 17) DAY, '20:30:00')
FROM users u
WHERE u.role = 'student' AND CAST(REGEXP_SUBSTR(u.dept, '[0-9]+') AS UNSIGNED) >= 4;

-- Ruby on Rails (Aug 2569): year 3+, about two thirds of them; 1016 didn't come.
INSERT INTO registrations (id, event_id, user_id, dept, status, checked_in, checked_in_at, attend_via, registered_at)
SELECT 105800 + ROW_NUMBER() OVER (ORDER BY u.id), 1058, u.id, u.dept,
       IF(u.id = 1016, 'absent', 'attended'), IF(u.id = 1016, 0, 1),
       IF(u.id = 1016, NULL, TIMESTAMP('2026-08-16', '16:15:00')), 'onsite',
       TIMESTAMP('2026-07-27' + INTERVAL (u.id % 17) DAY, '18:45:00')
FROM users u
WHERE u.role = 'student' AND CAST(REGEXP_SUBSTR(u.dept, '[0-9]+') AS UNSIGNED) >= 3 AND u.id % 3 <> 1;

-- AWS (Aug 2569): every student in year 3+; a few online; 1007 didn't come.
INSERT INTO registrations (id, event_id, user_id, dept, status, checked_in, checked_in_at, attend_via, registered_at)
SELECT 105900 + ROW_NUMBER() OVER (ORDER BY u.id), 1059, u.id, u.dept,
       IF(u.id = 1007, 'absent', 'attended'), IF(u.id = 1007, 0, 1),
       IF(u.id = 1007, NULL, TIMESTAMP('2026-08-19', '16:00:00')),
       IF(u.id IN (1003, 1016, 1020), 'online', 'onsite'),
       TIMESTAMP('2026-07-24' + INTERVAL (u.id % 15) DAY, '21:15:00')
FROM users u
WHERE u.role = 'student' AND CAST(REGEXP_SUBSTR(u.dept, '[0-9]+') AS UNSIGNED) >= 3;

-- ------------------------------------------------------------------ check-ins, every day of each event
INSERT INTO registration_checkins (registration_id, event_date, checked_in_at)
SELECT r.id, d.day, TIMESTAMP(d.day, SEC_TO_TIME(8 * 3600 + 5 * 60 + (r.id % 24) * 60))
FROM registrations r
JOIN (SELECT 1057 AS event_id, DATE '2026-01-11' AS day
      UNION ALL SELECT 1058, DATE '2026-08-15' UNION ALL SELECT 1058, DATE '2026-08-16'
      UNION ALL SELECT 1059, DATE '2026-08-18' UNION ALL SELECT 1059, DATE '2026-08-19') d ON d.event_id = r.event_id
WHERE r.checked_in = 1;

